def drive(me, enemy, arena):
    try:
        if not me.can_drive:
            return (0.0, 0.0)
        b = bearing_to(enemy.x, enemy.y)
        d = distance_to(enemy.x, enemy.y)
        # near wall behind us while reversing? escape forward toward centre
        rr = (me.x * me.x + me.y * me.y) ** 0.5
        h = radians(me.heading)
        bx = me.x - 0.7 * -cos(h) * -1  # point ahead; rear point below
        rearx = me.x + 0.7 * cos(h + radians(180)) * -1
        rearx = me.x - 0.7 * cos(h)
        reary = me.y - 0.7 * sin(h)
        rear_r = (rearx * rearx + reary * reary) ** 0.5
        behind = abs(b) > 110
        if behind and rear_r > arena.radius - 0.6:
            # rear blocked: turn so front faces centre, drive forward
            c = bearing_to(0.0, 0.0)
            if c > 15:
                return (1.0, 0.2)
            if c < -15:
                return (0.2, 1.0)
            return (1.0, 1.0)
        if behind:
            # reverse into them, spinner teeth first, with mild rear steering
            if b > 110:
                return (-1.0, max(-1.0, -1.0 + (180.0 - b) * 0.03))
            if b < -110:
                return (max(-1.0, -1.0 + (180.0 + b) * 0.03), -1.0)
            return (-1.0, -1.0)
        # enemy ahead or beside: swing our rear toward them, keep moving
        if d < 1.2 and abs(b) < 50:
            # too close head-on: push through past their side
            if b >= 0:
                return (0.9, 0.35)
            return (0.35, 0.9)
        if b >= 0:
            return (0.3, 1.0)   # enemy left: turn right (rear toward them)
        return (1.0, 0.3)       # enemy right: turn left
    except Exception:
        return (0.5, 0.5)

